<script setup lang="ts">
import { computed,ref,watch } from 'vue'
import { api,dateTimeLabel,messageOf,notify } from '../api'
import { exportFormatLabel,exportKind,type ExportFormat,type ExportSourceKind } from '../exports'
import Modal from './Modal.vue'
import Pager from './Pager.vue'
interface Storage {files:number;bytes:number;jobs:Record<string,number>;jobs_total:number}
interface Candidate {id:string;version:number;output_name:string;output_sha256:string;size:number;source_kind:ExportSourceKind;source_id:string;format:ExportFormat;created_at:string;updated_at:string}
interface Preview {days:number;before:string;source_kind?:string;items:Candidate[];total:number;bytes:number;skipped:number}
interface CleanupResult {items:Array<{id:string;ok:boolean;state?:string;version?:number;bytes?:number;code?:string;error?:string}>;total:number;cleaned:number;bytes:number;failed:number}
const props=defineProps<{revision:number}>(),emit=defineEmits<{changed:[]}>(),opened=ref(false),stats=ref<Storage>(),days=ref(30),preview=ref<Preview>(),selected=ref<string[]>([]),loading=ref(false),previewing=ref(false),cleaning=ref(false),error=ref(''),confirming=ref(false),acknowledged=ref(false),result=ref<CleanupResult>(),offset=ref(0),limit=15
let statsRequest=0,previewRequest=0
const candidates=computed(()=>preview.value?.items||[]),pageItems=computed(()=>candidates.value.slice(offset.value,offset.value+limit)),chosen=computed(()=>candidates.value.filter(item=>selected.value.includes(item.id))),selectedBytes=computed(()=>chosen.value.reduce((sum,item)=>sum+item.size,0)),allSelected=computed(()=>candidates.value.length>0&&chosen.value.length===candidates.value.length)
function bytes(value:number){if(value<1024)return `${value} B`;if(value<1024**2)return `${(value/1024).toFixed(1)} KB`;if(value<1024**3)return `${(value/1024**2).toFixed(1)} MB`;return `${(value/1024**3).toFixed(2)} GB`}
async function load(){if(!opened.value)return;const seq=++statsRequest;loading.value=true;try{const data=await api<Storage>('/api/export-storage');if(seq===statsRequest)stats.value=data}catch(e){if(seq===statsRequest)error.value=messageOf(e)}finally{if(seq===statsRequest)loading.value=false}}
async function inspect(){if(cleaning.value||previewing.value)return;const seq=++previewRequest;previewing.value=true;error.value='';result.value=undefined;selected.value=[];preview.value=undefined;offset.value=0;try{const data=await api<Preview>('/api/export-storage/cleanup-preview',{method:'POST',body:JSON.stringify({days:days.value})});if(seq===previewRequest)preview.value=data}catch(e){if(seq===previewRequest)error.value=messageOf(e)}finally{if(seq===previewRequest)previewing.value=false}}
function invalidate(){previewRequest++;preview.value=undefined;selected.value=[];result.value=undefined;offset.value=0}
function toggle(event:Event){opened.value=(event.target as HTMLDetailsElement).open;if(opened.value)void load()}
function selectAll(event:Event){selected.value=(event.target as HTMLInputElement).checked?candidates.value.map(item=>item.id):[]}
function confirm(){if(!chosen.value.length||chosen.value.length>5000||cleaning.value)return;acknowledged.value=false;confirming.value=true}
async function clean(){if(cleaning.value||!acknowledged.value||!chosen.value.length)return;const items=chosen.value.map(item=>({id:item.id,version:item.version}));cleaning.value=true;error.value='';try{result.value=await api<CleanupResult>('/api/export-storage/cleanup',{method:'POST',body:JSON.stringify({items})});confirming.value=false;preview.value=undefined;selected.value=[];notify(result.value.failed?`已清理 ${result.value.cleaned} 项，${result.value.failed} 项未清理，请查看结果`:`已清理 ${result.value.cleaned} 项生成文件，来源与任务保留`,result.value.failed>0);emit('changed');await load()}catch(e){error.value=messageOf(e)}finally{cleaning.value=false}}
watch(()=>props.revision,()=>{if(!cleaning.value){invalidate();void load()}})
defineExpose({canLeave:()=>!cleaning.value})
</script>
<template><details class="surface export-storage" @toggle="toggle"><summary>生成文件维护 <span>查看占用，按预览手动清理</span></summary><div class="storage-body"><p class="input-hint">仅清理导出生成的文件，保留原始来源、冻结快照、模板和导出任务。需要时可按任务的原快照重新生成。</p><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="storage-stats"><p v-if="loading&&!stats">正在统计…</p><template v-if="stats"><strong>{{stats.files}} 个生成文件 · {{bytes(stats.bytes)}}</strong><span>导出任务 {{stats.jobs_total}} 个：排队 {{stats.jobs.queued||0}} · 生成中 {{stats.jobs.running||0}} · 成功 {{stats.jobs.succeeded||0}} · 失败 {{stats.jobs.failed||0}}</span></template><button type="button" class="text-button" :disabled="loading||cleaning" @click="load">刷新统计</button></div><form class="storage-controls" @submit.prevent="inspect"><label>文件范围<select v-model.number="days" :disabled="previewing||cleaning" aria-label="清理生成文件范围" @change="invalidate"><option :value="7">超过 7 天</option><option :value="30">超过 30 天</option><option :value="90">超过 90 天</option><option :value="0">全部生成文件</option></select></label><button class="button subtle small" :disabled="previewing||cleaning">{{previewing?'正在预览…':'预览候选文件'}}</button></form><p class="input-hint">以导出任务最近更新时间计算；只列出成功且文件校验正常的候选项。预览不会删除文件。</p>
<template v-if="preview"><p class="storage-preview-summary">候选 {{preview.total}} 项 · {{bytes(preview.bytes)}} <span v-if="preview.skipped">· 跳过 {{preview.skipped}} 项</span></p><div v-if="candidates.length"><div class="storage-selection"><label class="checkbox-label"><input type="checkbox" :checked="allSelected" :disabled="cleaning" @change="selectAll"/>选择全部 {{candidates.length}} 个候选文件</label><span>已选 {{chosen.length}} 项 · {{bytes(selectedBytes)}}</span><button type="button" class="button subtle small" :disabled="!chosen.length||chosen.length>5000||cleaning" @click="confirm">清理所选生成文件…</button></div><p v-if="chosen.length>5000" class="form-error">每次最多清理 5000 个文件，请减少所选数量。</p><div class="table-scroll"><table><thead><tr><th class="check-cell">选择</th><th>文件 / 来源</th><th>大小</th><th>任务更新时间</th></tr></thead><tbody><tr v-for="item in pageItems" :key="item.id"><td class="check-cell"><input v-model="selected" type="checkbox" :value="item.id" :disabled="cleaning" :aria-label="`选择清理 ${item.output_name}`"/></td><td>{{item.output_name}}<small>{{exportKind(item.source_kind)}} · {{exportFormatLabel(item.format)}} · {{item.source_id}}</small></td><td>{{bytes(item.size)}}</td><td>{{dateTimeLabel(item.updated_at)}}</td></tr></tbody></table></div><Pager :offset="offset" :limit="limit" :total="candidates.length" @change="offset=$event"/></div><p v-else class="empty-state compact">此范围没有可清理的生成文件。</p></template>
<section v-if="result" class="cleanup-result" role="status"><h3>清理结果：{{result.cleaned}} 项成功，{{result.failed}} 项未清理 · 释放 {{bytes(result.bytes)}}</h3><ul><li v-for="item in result.items" :key="item.id" :class="{failed:!item.ok}">{{item.id}}：{{item.ok?'生成文件已清理':item.error||item.code||'未清理'}}<span v-if="item.ok">（来源和任务保留）</span></li></ul><p v-if="result.failed" class="input-hint">未清理项保持原状。重新预览可读取当前版本后再选择。</p></section></div></details>
<Modal :open="confirming" title="确认清理所选生成文件" @close="!cleaning&&(confirming=false)"><div class="modal-body"><p>本次将清理 {{chosen.length}} 个生成文件，约 {{bytes(selectedBytes)}}。</p><p class="cleanup-confirm-note">保留来源内容、冻结快照、模板与导出任务。下载链接会失效，需要时须按原快照重新生成。</p><ul class="cleanup-confirm-list"><li v-for="item in chosen" :key="item.id">{{item.output_name}}</li></ul><label class="checkbox-label"><input v-model="acknowledged" type="checkbox" :disabled="cleaning"/>我确认仅清理这些生成文件，保留来源和任务</label><p v-if="error" class="form-error" role="alert">{{error}}</p><div class="modal-footer"><button type="button" class="button subtle" :disabled="cleaning" @click="confirming=false">取消</button><button type="button" class="button primary" :disabled="!acknowledged||cleaning" @click="clean">{{cleaning?'正在清理…':'确认清理生成文件'}}</button></div></div></Modal>
</template>
<style scoped>.export-storage{margin-top:22px}.export-storage>summary{font-weight:600;font-size:14px;padding:18px 20px;cursor:pointer}.export-storage>summary>span{font-size:11px;font-weight:400;color:var(--muted);margin-left:12px}.storage-body{padding:0 20px 20px}.storage-stats{display:flex;align-items:baseline;flex-wrap:wrap;gap:8px 16px;margin:18px 0;font-size:12px}.storage-stats>span{font-size:11px;color:var(--muted)}.storage-controls{display:flex;align-items:flex-end;gap:12px;flex-wrap:wrap;margin-bottom:10px}.storage-controls label{margin:0;font-size:12px}.storage-controls select{margin-top:5px;min-width:170px}.storage-preview-summary{margin:18px 0;font-size:13px}.storage-selection{display:flex;gap:12px;align-items:center;flex-wrap:wrap;padding:12px 0;font-size:12px}.storage-selection>.checkbox-label{margin:0}.storage-selection>span{color:var(--muted)}.storage-body table{min-width:650px}.storage-body td{overflow-wrap:anywhere}.cleanup-result{padding-top:18px;border-top:1px solid var(--border);margin-top:18px}.cleanup-result h3{font-size:13px}.cleanup-result ul{padding-left:18px;font-size:11px;line-height:1.9;overflow-wrap:anywhere}.cleanup-result .failed{color:#a55543}.cleanup-confirm-note{line-height:1.8;font-size:12px;margin:12px 0;color:var(--muted)}.cleanup-confirm-list{max-height:180px;overflow:auto;padding-left:20px;font-size:12px;line-height:1.9;overflow-wrap:anywhere}@media(max-width:650px){.storage-body{padding:0 15px 15px}.export-storage>summary>span{display:block;margin:5px 0 0 15px}}
</style>
